--
-- Name: v_alert_overview; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_alert_overview AS
 SELECT al.alert_id,
    al.rule_id,
    al.detection_method,
    al.severity,
    al.status,
    (al.status <> 'resolved'::text) AS is_active,
    al.title,
    al.summary,
    al.first_ts,
    al.last_ts,
    al.incident_id,
    a.name AS asset_name,
    a.asset_type,
    st.code AS system,
    l.name AS zone
   FROM (((public.alerts al
     JOIN public.assets a ON ((a.asset_id = al.asset_id)))
     JOIN public.system_types st ON ((st.system_type_id = a.system_type_id)))
     JOIN public.locations l ON ((l.location_id = a.location_id)));


ALTER VIEW public.v_alert_overview OWNER TO postgres;

