-- Name: v_data_clock; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_data_clock AS
 SELECT GREATEST(( SELECT max(telemetry_records.ts) AS max
           FROM public.telemetry_records), ( SELECT max(event_records.ts) AS max
           FROM public.event_records)) AS as_of;


ALTER VIEW public.v_data_clock OWNER TO postgres;

--
-- Name: v_asset_overview; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_asset_overview AS
 WITH clk AS (
         SELECT v_data_clock.as_of
           FROM public.v_data_clock
        ), ev AS (
         SELECT er.asset_id,
            count(*) FILTER (WHERE (er.severity = 'critical'::text)) AS critical_events_24h,
            count(*) FILTER (WHERE (er.severity = 'warning'::text)) AS warning_events_24h,
            count(*) FILTER (WHERE (et.name = 'heartbeat'::text)) AS heartbeats_24h
           FROM (public.event_records er
             JOIN public.event_types et ON ((et.event_type_id = er.event_type_id))),
            clk
          WHERE ((er.ts > (clk.as_of - '24:00:00'::interval)) AND (er.ts <= clk.as_of))
          GROUP BY er.asset_id
        ), tel AS (
         SELECT t.asset_id,
            count(*) AS telemetry_24h
           FROM public.telemetry_records t,
            clk
          WHERE ((t.ts > (clk.as_of - '24:00:00'::interval)) AND (t.ts <= clk.as_of))
          GROUP BY t.asset_id
        ), reports AS (
         SELECT telemetry_records.asset_id
           FROM public.telemetry_records
          GROUP BY telemetry_records.asset_id
        UNION
         SELECT er.asset_id
           FROM (public.event_records er
             JOIN public.event_types et ON ((et.event_type_id = er.event_type_id)))
          WHERE (et.name = 'heartbeat'::text)
        ), seen AS (
         SELECT u.asset_id,
            max(u.ts) AS last_seen
           FROM ( SELECT telemetry_records.asset_id,
                    telemetry_records.ts
                   FROM public.telemetry_records
                UNION ALL
                 SELECT event_records.asset_id,
                    event_records.ts
                   FROM public.event_records) u
          GROUP BY u.asset_id
        ), alr AS (
         SELECT alerts.asset_id,
            count(*) AS open_alerts
           FROM public.alerts
          WHERE (alerts.status <> 'resolved'::text)
          GROUP BY alerts.asset_id
        )
 SELECT a.asset_id,
    a.name AS asset_name,
    a.asset_type,
    st.code AS system,
    l.name AS zone,
    l.floor,
    b.name AS building,
        CASE
            WHEN (COALESCE(ev.critical_events_24h, (0)::bigint) > 0) THEN 'critical'::text
            WHEN ((a.asset_id IN ( SELECT reports.asset_id
               FROM reports)) AND (COALESCE(tel.telemetry_24h, (0)::bigint) = 0) AND (COALESCE(ev.heartbeats_24h, (0)::bigint) = 0)) THEN 'no_data'::text
            WHEN (COALESCE(ev.warning_events_24h, (0)::bigint) > 0) THEN 'warning'::text
            ELSE 'normal'::text
        END AS health_24h,
    COALESCE(ev.critical_events_24h, (0)::bigint) AS critical_events_24h,
    COALESCE(ev.warning_events_24h, (0)::bigint) AS warning_events_24h,
    COALESCE(alr.open_alerts, (0)::bigint) AS open_alerts,
    seen.last_seen
   FROM (((((((public.assets a
     JOIN public.system_types st ON ((st.system_type_id = a.system_type_id)))
     JOIN public.locations l ON ((l.location_id = a.location_id)))
     JOIN public.buildings b ON ((b.building_id = l.building_id)))
     LEFT JOIN ev ON ((ev.asset_id = a.asset_id)))
     LEFT JOIN tel ON ((tel.asset_id = a.asset_id)))
     LEFT JOIN seen ON ((seen.asset_id = a.asset_id)))
     LEFT JOIN alr ON ((alr.asset_id = a.asset_id)));


ALTER VIEW public.v_asset_overview OWNER TO postgres;

--
-- Name: v_camera_status; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_camera_status AS
 SELECT a.asset_id,
    a.name AS asset_name,
    l.name AS zone,
    max(er.ts) FILTER (WHERE (et.name = 'camera_offline'::text)) AS last_offline,
    max(er.ts) FILTER (WHERE (et.name = 'camera_online'::text)) AS last_online,
    COALESCE((max(er.ts) FILTER (WHERE (et.name = 'camera_offline'::text)) > COALESCE(max(er.ts) FILTER (WHERE (et.name = 'camera_online'::text)), '-infinity'::timestamp with time zone)), false) AS is_offline
   FROM (((public.assets a
     JOIN public.locations l ON ((l.location_id = a.location_id)))
     LEFT JOIN public.event_records er ON ((er.asset_id = a.asset_id)))
     LEFT JOIN public.event_types et ON (((et.event_type_id = er.event_type_id) AND (et.name = ANY (ARRAY['camera_offline'::text, 'camera_online'::text])))))
  WHERE (a.asset_type = 'camera'::text)
  GROUP BY a.asset_id, a.name, l.name;


ALTER VIEW public.v_camera_status OWNER TO postgres;

